def overlay(name, a, b, owner, note):
    """Put (a, b, owner, note) into a region's timeline, cutting the ranges it overlaps (AD years only)."""
    out = []
    for x, y, o, n in REGIONS[name][2]:
        if y < a or x > b:
            out.append((x, y, o, n))
            continue
        if x < a:
            out.append((x, a - 1, o, n))
        if y > b:
            out.append((b + 1, y, o, n))
    out.append((a, b, owner, note))
    REGIONS[name] = (REGIONS[name][0], REGIONS[name][1], sorted(out))


# The Gallic Empire (260–274): Gaul, the Rhine provinces and Britain under their own emperors; Spain until about 269,
# the Rhône valley until Claudius II's general took it back around 269.
for r in ("septimania", "helvetia", "aedui", "lugdunum", "arverni", "carnutes", "seine", "belgica_s", "belgica_n", "toxandria",
          "treveri", "armorica", "aquitania", "germania_sup", "germania_inf", "brit_se", "brit_sw", "brit_mid", "iceni", "wales", "brigantia"):
    overlay(r, 260, 273, "gallic", None)
for r in ("provincia", "sapaudia", "tarraco", "ebro", "levante", "carthago_nova", "baetica", "lusitania", "celtiberia", "gallaecia", "cantabria", "vasconia"):
    overlay(r, 260, 268, "gallic", None)
